import {lessons,organelles,defaultState,cleanState,experimentRate,xpFor,escapeHTML as esc,normalize} from './learning.js';
import {initExhibition} from './exhibition.js';
const icons={
 sprout:'M12 22v-9M12 17C5 17 2 13 2 7c7 0 10 3 10 10Zm0-5C12 5 16 2 22 2c0 7-3 10-10 10Z',leaf:'M20 4C9 1 2 7 4 15c2 7 13 7 16-11ZM4 21 15 10M8 17v-5m3 2h5',search:'m21 21-4.4-4.4M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',menu:'M4 6h16M4 12h16M4 18h16',x:'m6 6 12 12M6 18 18 6','arrow-up-right':'M6 18 18 6M6 6h12v12','arrow-right':'M4 12h16m-6-6 6 6-6 6','arrow-down':'M12 4v16m-6-6 6 6 6-6','chevron-down':'m6 9 6 6 6-6',play:'m9 5 11 7-11 7Z',orbit:'M20 12a8 8 0 1 1-8-8M20 4a2 2 0 1 1-4 0 2 2 0 0 1 4 0M19 7c3 3 1 6-4 9S4 20 2 17s0-6 5-9 7-3 9-2',flask:'M9 3h6M10 3v6L4 19a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2L14 9V3M7 15h10',route:'M7 4a2 2 0 1 1-4 0 2 2 0 0 1 4 0M21 20a2 2 0 1 1-4 0 2 2 0 0 1 4 0M5 6v9a4 4 0 0 0 8 0V9a4 4 0 0 1 8 0v9','book-open':'M12 5v16M12 5C9 3 5 3 2 4v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1Z',box:'m12 3 9 5v9l-9 5-9-5V8Zm0 10 9-5M3 8l9 5v9M7 5l9 5',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bookmark:'M6 3h12v19l-6-4-6 4Z',move:'M12 2v20M2 12h20m-13-7 3-3 3 3M9 19l3 3 3-3M5 9l-3 3 3 3m14-6 3 3-3 3',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',chart:'M4 3v17h17M7 15l4-5 4 3 6-7',notebook:'M5 3h15v18H5ZM2 7h6m-6 5h6m-6 5h6M11 7h5m-5 5h5',award:'M12 3a6 6 0 1 1 0 12 6 6 0 0 1 0-12M8 14l-2 8 6-3 6 3-2-8',quote:'M10 5H3v8h5c0 4-2 5-4 6m17-14h-7v8h5c0 4-2 5-4 6',check:'m5 12 4 4L20 5',droplet:'M12 2C10 7 4 11 4 16a8 8 0 0 0 16 0c0-5-6-9-8-14Z',dna:'M7 2c-9 11 19 9 10 20M17 2C26 13-2 11 7 22M8 5h8M6 9h12M6 15h12m-10 4h8',layers:'m12 3 10 5-10 5L2 8Zm-9 9 9 5 9-5m-18 5 9 5 9-5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',rotate:'M3 3v6h6M3 9a9 9 0 1 1 0 7',plus:'M12 4v16M4 12h16',minus:'M4 12h16',pause:'M8 4v16M16 4v16',external:'M14 3h7v7M10 14 21 3M21 14v7H3V3h7',microscope:'M10 2h5v4h-5Zm1 4-4 8 4 2 5-9M7 14c-4 0-4 6 1 6h12M18 11c5 4 3 9-4 9M5 22h15',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1s-2 6 0 8l8 8 8-8c2-2 3-5 0-8',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.leaf}"/></svg>`}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon')})}
hydrate();
let state;let storageAvailable=true;
try{state=cleanState(JSON.parse(localStorage.getItem('vnscape-v1')))}catch{state=cleanState(defaultState)}
const dialog=document.querySelector('#app-dialog'),content=document.querySelector('#dialog-content');let activeModel=null,modelSerial=0,activeLesson=null,quizCorrect=false,toastTimer;let modalType='';
function persist(){try{localStorage.setItem('vnscape-v1',JSON.stringify(state))}catch{if(storageAvailable)toast('Trình duyệt không cho lưu dữ liệu. Phiên này vẫn dùng được.');storageAvailable=false}updateProgress()}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
function updateProgress(){
 document.querySelector('#xp-count').textContent=xpFor(state);document.querySelector('#progress-label').textContent=`${state.completed.length} / 6 bài học`;document.querySelector('#progress-fill').style.width=`${state.completed.length/6*100}%`;
 document.querySelector('#badge-first').classList.toggle('earned',state.completed.length>0);document.querySelector('#badge-lab').classList.toggle('earned',state.trials.length>0);document.querySelector('#badge-all').classList.toggle('earned',[10,11,12].every(g=>lessons.some(x=>x.grade===g&&state.completed.includes(x.id))));
 document.querySelector('#next-lesson-label').textContent=state.completed.length===6?'Xem lại hành trình đã hoàn thành':state.completed.length?'Tiếp tục với một khám phá mới':'Khám phá bài học đầu tiên';
 document.querySelector('.profile-button .avatar').textContent=state.name==='Nhà thám hiểm'?'K':state.name[0]?.toUpperCase()||'K';
 document.querySelector('.progress-card-top h3').textContent=state.name==='Nhà thám hiểm'?'Chào bạn, nhà thám hiểm!':`Chào ${state.name}!`;
 document.querySelectorAll('[data-grade]').forEach(b=>{const selected=Number(b.dataset.grade)===state.grade;b.classList.toggle('selected',selected);b.setAttribute('aria-selected',selected);b.tabIndex=selected?0:-1});
}
function renderTopics(){
 const list=lessons.filter(x=>x.grade===state.grade);document.querySelector('#topic-grid').innerHTML=list.map((l,i)=>`<article class="topic-card ${i===0?'featured':''}"><div class="topic-image">${l.image?`<img src="assets/${l.image}" alt="${l.id==='photosynthesis'?'Lá xanh dưới ánh sáng tự nhiên':'Mô hình minh họa cấu trúc sinh học'}" loading="lazy">`:`<div class="topic-illustration illustration-${l.visual}">${icon(l.visual==='membrane'?'layers':l.visual==='water'?'droplet':l.visual==='dna'?'dna':'sprout')}</div>`}<span class="topic-type">${icon(l.icon)} ${l.type}</span><button class="bookmark-button ${state.saved.includes(l.id)?'saved':''}" data-action="bookmark" data-id="${l.id}" aria-label="${state.saved.includes(l.id)?'Bỏ lưu':'Lưu'} bài ${l.title}" aria-pressed="${state.saved.includes(l.id)}">${icon('bookmark')}</button>${state.completed.includes(l.id)?`<span class="lesson-done">${icon('check')} Đã khám phá</span>`:''}</div><div class="topic-body"><span class="topic-kicker">${l.kicker}</span><h3>${l.title}</h3><p>${l.description}</p><div class="topic-bottom"><span>${icon('clock')} ${l.minutes} phút · Lớp ${l.grade}</span><button data-action="lesson" data-id="${l.id}">Khám phá ${icon('arrow-up-right')}</button></div></div></article>`).join('')+`<article class="topic-card"><div class="topic-image"><img src="assets/forest.jpg" alt="Khung cảnh thiên nhiên để bắt đầu quan sát" loading="lazy"><span class="topic-type">${icon('leaf')} Nhiệm vụ thực địa</span></div><div class="topic-body"><span class="topic-kicker">KHOA HỌC NGAY QUANH BẠN</span><h3>${state.grade===10?'Nhìn chiếc lá, thấy tế bào':state.grade===11?'Theo dấu một mầm xanh':'Đa dạng ngay sân trường'}</h3><p>${state.grade===10?'Bắt đầu từ một chiếc lá thật và những câu hỏi chưa có lời giải.':state.grade===11?'Quan sát một cây quen thuộc và đặt câu hỏi về cách nó sống.':'Ghi lại những dạng sống quanh bạn. Điều gì khiến chúng khác nhau?'}</p><div class="topic-bottom"><span>${icon('sun')} Ngoài màn hình</span><button data-action="mission">Nhận nhiệm vụ ${icon('arrow-up-right')}</button></div></div></article>`;
 updateProgress();
}
function showDialog(title,eyebrow,html,type=''){
 disposeModel();modalType=type;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-eyebrow').textContent=eyebrow;content.innerHTML=html;hydrate(content);dialog.classList.toggle('model-dialog',type==='model');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden';
}
function disposeModel(){modelSerial++;if(activeModel){activeModel.dispose();activeModel=null}}
dialog.addEventListener('close',()=>{disposeModel();document.body.style.overflow='';modalType=''});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function fallback(container,type,select=()=>{}){container.innerHTML=`<div class="model-fallback">${icon(type==='dna'?'dna':'layers')}<p>Thiết bị hiện không hỗ trợ hiển thị WebGL.<br>Bạn vẫn có thể khám phá qua sơ đồ và chú giải.</p>${type==='cell'?`<div class="fallback-schematic">${Object.entries(organelles).map(([id,o])=>`<button data-organelle="${id}">${o.name}</button>`).join('')}</div>`:'<p>A — T &nbsp; · &nbsp; G — C<br>Hai mạch bổ sung, ngược chiều nhau</p>'}</div>`;container.querySelectorAll('[data-organelle]').forEach(b=>b.onclick=()=>select(b.dataset.organelle))}
async function mountModel(type){const serial=modelSerial;const el=document.querySelector('#model-canvas');if(!el)return;try{const {createModel}=await import('./models.js');if(serial!==modelSerial||!dialog.open)return;activeModel=createModel(el,type,{onSelect:id=>{if(type==='cell')selectOrganelle(id)}})}catch{if(serial===modelSerial)fallback(el,type,selectOrganelle)}}
function selectOrganelle(id){const o=organelles[id];if(!o)return;activeModel?.select(id);content.querySelectorAll('[data-organelle]').forEach(b=>{b.classList.toggle('selected',b.dataset.organelle===id);b.setAttribute('aria-pressed',b.dataset.organelle===id)});const el=document.querySelector('#organelle-detail');if(el)el.innerHTML=`<span class="small-label">${o.tag}</span><h3>${o.name}</h3><p>${o.text}</p><div class="fact-note">${o.fact}</div>`}
function openModel(type='cell'){
 type=type==='dna'?'dna':'cell';const cell=type==='cell';if(!state.viewed.includes(type)){state.viewed.push(type);persist()}
 showDialog(cell?'Một thế giới trong tế bào':'Mật mã của sự sống','THƯ VIỆN TƯƠNG TÁC / '+(cell?'SINH HỌC TẾ BÀO':'DI TRUYỀN HỌC'),`<p class="dialog-lead">${cell?'Kéo để xoay mô hình, chạm vào bào quan hoặc chọn tên bên cạnh để khám phá chức năng.':'Kéo để xoay chuỗi xoắn kép. Hãy chú ý hai mạch và các cặp base ở phía trong.'}</p><div class="modal-columns"><div><div class="model-viewer" id="model-canvas"><span class="viewer-tip">${icon('move')} KÉO ĐỂ XOAY · CUỘN ĐỂ PHÓNG TO</span></div><div class="viewer-tools"><button data-action="model-auto">${icon('pause')} <span>Tự xoay</span></button><div style="display:flex;gap:6px"><button data-action="zoom-in" aria-label="Phóng to">${icon('plus')}</button><button data-action="zoom-out" aria-label="Thu nhỏ">${icon('minus')}</button><button data-action="model-reset" aria-label="Đặt lại góc nhìn">${icon('rotate')}</button></div></div><p class="model-disclaimer">Mô hình minh họa ${cell?'cắt lớp chọn lọc':'ADN dạng xoắn kép'} · Màu quy ước · Không theo tỉ lệ.</p><p class="model-keyboard">Bàn phím: Tab vào mô hình, dùng phím mũi tên để xoay và + / − để phóng to, thu nhỏ.</p></div><div>${cell?`<div class="organelle-list">${Object.entries(organelles).map(([id,o])=>`<button data-organelle="${id}" aria-pressed="false">${o.name}</button>`).join('')}</div><div class="organelle-detail" id="organelle-detail" aria-live="polite"></div>`:`<div class="organelle-detail"><span class="small-label">NGUYÊN TẮC BỔ SUNG</span><h3>Hai mạch. Một kết nối.</h3><p>Khung đường–phosphate nằm ở ngoài, các cặp base nằm phía trong. Hai mạch ADN ngược chiều nhau.</p><div class="fact-note"><b style="color:#829f5a">A (xanh lá) — T (vàng đất)</b><br><b style="color:#7d98b5">G (xanh lam) — C (hồng tím)</b><br>Mô hình dùng chuỗi base minh họa, không đại diện cho một gene cụ thể.</div></div>`}<button class="dialog-link" data-action="lesson" data-id="${type}">Vào bài học & thử sức ${icon('arrow-right')}</button><button class="dialog-link" data-action="new-note" data-title="${cell?'Bên trong tế bào thực vật':'Khám phá chuỗi ADN'}">Ghi lại điều vừa khám phá ${icon('notebook')}</button></div></div>`,'model');
 dialog.classList.remove('is-lit');
 const isMoving=!matchMedia('(prefers-reduced-motion: reduce)').matches;
 const autoButton=content.querySelector('[data-action="model-auto"]');autoButton.setAttribute('aria-pressed',String(isMoving));autoButton.innerHTML=icon(isMoving?'pause':'play')+` <span>${isMoving?'Tự xoay':'Đã dừng'}</span>`;
 content.querySelector('.viewer-tools').insertAdjacentHTML('beforeend',`<button data-action="model-light" aria-pressed="false">${icon('sun')} <span>Đèn quan sát</span></button>`);
 if(cell)content.querySelector('.viewer-tools').insertAdjacentHTML('beforeend',`<button data-action="model-shell" aria-pressed="true">${icon('layers')} <span>Thành tế bào</span></button>`);
 if(cell)selectOrganelle('nucleus');mountModel(type);
}
function openLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;activeLesson=l;quizCorrect=false;showDialog(l.title,`HÀNH TRÌNH LỚP ${l.grade} / ${l.minutes} PHÚT`,`${state.completed.includes(id)?`<div class="fact-note">${icon('check')} Bạn đã hoàn thành bài này. Có thể khám phá và luyện tập lại bất cứ lúc nào.</div>`:''}<div class="lesson-layout"><div class="lesson-copy"><p>${l.intro}</p><h3>${l.heading}</h3><ul>${l.points.map(x=>`<li>${x}</li>`).join('')}</ul><div class="lesson-callout"><b>Bạn có biết?</b><br>${l.wonder}</div>${l.activity?`<button class="button button-dark" data-action="${l.activity==='lab'?'lab':'model'}" data-model="${l.activity==='dna'?'dna':'cell'}">${icon(l.activity==='lab'?'flask':'box')} ${l.activity==='lab'?'Tự thử trong phòng thí nghiệm':'Mở mô hình tương tác'}</button>`:''}<div class="lesson-footer"><button class="text-button" data-action="bookmark" data-id="${id}">${icon('bookmark')} <span id="lesson-bookmark-label">${state.saved.includes(id)?'Đã lưu bài học':'Lưu bài học'}</span></button><button class="text-button" data-action="new-note" data-title="${l.title}">${icon('notebook')} Ghi chép</button></div><p class="lesson-source">Tham khảo: <a href="${l.source}" target="_blank" rel="noopener">OpenStax Biology 2e ${icon('external')}</a> · Nội dung tóm lược cho bản trải nghiệm.</p></div><div class="quiz-card"><span class="quiz-title">DỪNG MỘT CHÚT. THỬ MỘT CÂU.</span><h3>${l.question}</h3><div class="quiz-options">${l.answers.map((a,i)=>`<button data-answer="${i}"><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${a}</span></button>`).join('')}</div><p class="quiz-feedback" id="quiz-feedback" aria-live="polite"></p><button class="button button-dark" id="complete-lesson" data-action="complete" disabled>Ghi dấu khám phá ${icon('check')}</button><p class="privacy-note">Trả lời đúng để hoàn thành · +30 XP lần đầu</p></div></div>`,'lesson')}
function answerQuiz(index){if(!activeLesson||modalType!=='lesson'||quizCorrect)return;const correct=index===activeLesson.correct;const b=content.querySelector(`[data-answer="${index}"]`);b?.classList.add(correct?'correct':'wrong');document.querySelector('#quiz-feedback').textContent=correct?`Chính xác! ${activeLesson.explanation}`:'Chưa đúng. Hãy xem lại phần giải thích và thử một lựa chọn khác.';if(correct){quizCorrect=true;document.querySelector('#complete-lesson').disabled=false;content.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true)}}
function completeLesson(){if(!quizCorrect||!activeLesson)return;const id=activeLesson.id;if(!state.completed.includes(id)){state.completed.push(id);persist();renderTopics();toast('Một mầm xanh mới! Bạn nhận được 30 XP.')}else toast('Bạn đã ôn lại bài học thành công.');openPath()}
function toggleBookmark(id){if(!lessons.some(x=>x.id===id))return;const saved=state.saved.includes(id);state.saved=saved?state.saved.filter(x=>x!==id):[...state.saved,id];persist();renderTopics();if(modalType==='notebook')openNotebook('saved');const label=document.querySelector('#lesson-bookmark-label');if(label)label.textContent=saved?'Lưu bài học':'Đã lưu bài học';toast(saved?'Đã bỏ lưu bài học.':'Đã lưu vào sổ tay của bạn.')}
function openLab(){showDialog('Nếu chiếc lá thiếu ánh sáng?','PHÒNG THÍ NGHIỆM / LỚP 11',`<p class="dialog-lead">Thay đổi từng yếu tố, ghi lại kết quả rồi so sánh. Giữ các điều kiện khác cố định và xem yếu tố nào đang giới hạn quá trình.</p><div class="modal-columns"><div><div class="lab-stage"><span class="lab-sun">${icon('sun')}</span>${icon('leaf')}<div class="oxygen-bubbles">${Array.from({length:12},(_,i)=>`<span class="oxygen-bubble" style="left:${20+i*5}%;animation-delay:${i*.33}s"></span>`).join('')}</div><div class="lab-rate">Chỉ số quang hợp minh họa<strong id="lab-rate">0%</strong></div><small>Chỉ số tương đối, không phải lượng O₂ hay số liệu đo thực nghiệm.</small></div><div class="fact-note" id="lab-observation" aria-live="polite"></div></div><div class="lab-controls"><div class="range-group"><label class="control-label" for="light-range">${icon('sun')} Ánh sáng <output id="light-output">50%</output></label><input id="light-range" type="range" min="0" max="100" value="50"><div class="range-endpoints"><span>Không có ánh sáng</span><span>Mạnh</span></div></div><div class="range-group"><label class="control-label" for="co2-range">${icon('leaf')} Mức cung cấp CO₂ <output id="co2-output">50%</output></label><input id="co2-range" type="range" min="0" max="100" value="50"><div class="range-endpoints"><span>Không cung cấp</span><span>Dồi dào</span></div></div><button class="button button-dark" data-action="record-trial">Ghi một lần thử ${icon('plus')}</button><p class="privacy-note">Đã lưu tối đa 20 lần thử gần nhất trên thiết bị.</p><div class="fact-note"><b>Giới hạn mô hình</b><br>Chỉ số = min(ánh sáng / 70, 1) × min(CO₂ / 65, 1) × 100%. Đây là quy tắc sư phạm đơn giản, giả định nước và nhiệt độ phù hợp; bỏ qua hô hấp và tác hại của ánh sáng quá mạnh.</div></div></div><div id="trial-results"></div><div class="modal-actions"><button class="button button-dark" data-action="save-lab-note">Lưu kết quả vào sổ tay ${icon('notebook')}</button><button class="text-button" data-action="lesson" data-id="photosynthesis">Hiểu sâu & thử sức ${icon('arrow-right')}</button></div>`,'lab');updateLab();renderTrials()}
function updateLab(){const light=Number(document.querySelector('#light-range')?.value||0),co2=Number(document.querySelector('#co2-range')?.value||0),rate=experimentRate(light,co2);document.querySelector('#light-output').textContent=`${light}%`;document.querySelector('#co2-output').textContent=`${co2}%`;document.querySelector('#lab-rate').textContent=`${rate}%`;document.querySelector('.lab-sun').style.opacity=light/100;content.querySelectorAll('.oxygen-bubble').forEach((x,i)=>{x.style.display=i<Math.ceil(rate/9)?'block':'none';x.style.animationDuration=`${6-rate*.035}s`});document.querySelector('#lab-observation').textContent=light===0?'Không có ánh sáng: chỉ số bằng 0 dù có thêm CO₂. Hãy giữ ánh sáng bằng 0 rồi thay đổi CO₂ để kiểm tra.':co2===0?'Không có CO₂ được cung cấp: chỉ số bằng 0 trong mô hình. Ánh sáng một mình chưa đủ.':light>=70&&co2>=65?'Hai yếu tố đã đạt ngưỡng bão hòa của mô hình. Tăng thêm sẽ không làm chỉ số tăng.':light/70<co2/65?'Ánh sáng đang được cung cấp ít hơn so với ngưỡng của mô hình. Hãy giữ CO₂ và thử tăng ánh sáng.':'CO₂ đang được cung cấp ít hơn so với ngưỡng của mô hình. Hãy giữ ánh sáng và thử tăng CO₂.';return{light,co2,rate}}
function renderTrials(){const el=document.querySelector('#trial-results');if(!el)return;el.innerHTML=state.trials.length?`<table class="trial-table"><caption style="text-align:left;margin-top:18px;font-size:11px">Nhật ký thí nghiệm trên thiết bị này</caption><thead><tr><th>Lần thử</th><th>Ánh sáng</th><th>CO₂</th><th>Chỉ số</th></tr></thead><tbody>${state.trials.map((t,i)=>`<tr><td>${i+1}</td><td>${t.light}%</td><td>${t.co2}%</td><td>${t.rate}%</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state" style="margin-top:20px">Chưa có lần thử nào. Hãy đặt điều kiện và ghi kết quả đầu tiên.</div>`}
function recordTrial(){if(modalType!=='lab')return;state.trials.push(updateLab());state.trials=state.trials.slice(-20);persist();renderTrials();toast(state.trials.length===1?'Đã ghi lần thử đầu tiên · +20 XP!':'Đã ghi kết quả. Thay đổi một yếu tố và thử so sánh.')}
function saveLabNote(){if(!state.trials.length){toast('Hãy ghi ít nhất một lần thử trước khi lưu.');return}addNote('Thí nghiệm: Ánh sáng & quang hợp',state.trials.map((x,i)=>`Lần ${i+1}: ánh sáng ${x.light}%, CO₂ ${x.co2}% → chỉ số ${x.rate}%.`).join('\n')+'\n\nMô hình minh họa định tính, không phải dữ liệu thực nghiệm.\nPhát hiện của tôi: ');openNotebook();toast('Đã lưu nhật ký thí nghiệm vào sổ tay.')}
function addNote(title,body){state.notes.unshift({id:crypto.randomUUID(),title,body,date:new Date().toISOString()});state.notes=state.notes.slice(0,100);persist()}
function formatDate(v){const d=new Date(v);return Number.isNaN(d.getTime())?'':d.toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',year:'numeric'})}
function openNotebook(tab='notes'){
 showDialog('Những điều mình tìm thấy','SỔ TAY KHÁM PHÁ',`<p class="dialog-lead">Có những câu hỏi đáng để giữ lại. Ghi ý tưởng, lưu bài hay và mang theo những phát hiện của riêng bạn.</p><div class="notebook-tabs"><button class="${tab==='notes'?'selected':''}" data-action="notes-tab">Ghi chép (${state.notes.length})</button><button class="${tab==='saved'?'selected':''}" data-action="saved-tab">Bài đã lưu (${state.saved.length})</button></div>${tab==='notes'?`<div class="modal-actions" style="margin:0 0 20px"><button class="button button-dark" data-action="new-note">Viết một phát hiện ${icon('plus')}</button><button class="text-button" data-action="export-notes">Xuất sổ tay ${icon('download')}</button></div>${state.notes.length?`<div class="note-list">${state.notes.map(n=>`<article class="note-item"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="note-item-footer"><span>${formatDate(n.date)}</span><div style="display:flex;gap:8px"><button data-action="edit-note" data-id="${esc(n.id)}">Sửa</button><button data-action="delete-note" data-id="${esc(n.id)}" aria-label="Xóa ghi chép ${esc(n.title)}">${icon('trash')}</button></div></div></article>`).join('')}</div>`:`<div class="empty-state">${icon('notebook')}Trang đầu tiên vẫn đang chờ một khám phá của bạn.</div>`}`:state.saved.length?`<div class="search-results">${state.saved.map(id=>resultHTML(lessons.find(x=>x.id===id))).join('')}</div>`:`<div class="empty-state">${icon('bookmark')}Chạm biểu tượng đánh dấu trên bài học để lưu vào đây.</div>`}<p class="privacy-note">Sổ tay lưu trong trình duyệt này. Hãy xuất bản sao trước khi xóa dữ liệu trình duyệt hoặc đổi thiết bị.</p>`,'notebook');
}
function openNoteForm(title='',body='',id=''){showDialog(id?'Chỉnh sửa ghi chép':'Một phát hiện mới','SỔ TAY / GHI LẠI ĐIỀU THÚ VỊ',`<form class="note-form" id="note-form" data-id="${esc(id)}"><label for="note-title">Tiêu đề</label><input id="note-title" name="title" value="${esc(title)}" maxlength="100" placeholder="Hôm nay mình đã tìm thấy…" required><label for="note-body">Điều bạn quan sát được hoặc muốn tìm hiểu thêm</label><textarea id="note-body" name="body" maxlength="6000" required placeholder="Mình quan sát thấy…\nMình nghĩ rằng…\nMình muốn kiểm tra bằng cách…">${esc(body)}</textarea><button class="button button-dark" type="submit">Lưu phát hiện ${icon('check')}</button></form><p class="privacy-note">Ghi chép là của bạn, lưu ngay trên thiết bị này.</p>`,'note-form')}
function openMission(){const prompt=state.grade===10?'Chọn một chiếc lá còn trên cây. Quan sát hình dạng, gân lá và hai mặt lá.\n\nMình quan sát thấy:\n\nNhững điều mắt thường chưa thể thấy (cần kính hiển vi):\n\nCâu hỏi mình muốn tìm hiểu:':state.grade===11?'Quan sát một cây ở hai thời điểm trong ngày. Ghi lại ánh sáng, điều kiện đất và trạng thái lá. Không bứt lá hoặc làm hại cây.\n\nThời điểm 1:\n\nThời điểm 2:\n\nĐiều khác biệt:\n\nMình cần kiểm tra thêm:':'Chọn một khu vực nhỏ trong sân trường. Ghi nhận các dạng thực vật bạn nhìn thấy, không tự kết luận quan hệ di truyền chỉ từ vẻ ngoài.\n\nCác dạng cây mình thấy:\n\nĐiểm giống và khác nhau:\n\nĐiều chưa biết:\n\nCách tìm nguồn xác minh:';openNoteForm(`Nhiệm vụ thực địa · Lớp ${state.grade}`,prompt)}
function resultHTML(l){return `<button class="search-result" data-action="lesson" data-id="${l.id}"><span>${icon(l.icon)}</span><div><h3>${l.title}</h3><small>Lớp ${l.grade} · ${l.type} · ${l.minutes} phút</small></div><span>${icon('arrow-right')}</span></button>`}
function openSearch(){showDialog('Một câu hỏi mới?','TÌM TRONG VNSCAPE',`<label for="lesson-search" class="dialog-lead" style="display:block">Tìm theo chủ đề, tên bài hoặc khối lớp. Gõ không dấu cũng được.</label><input class="search-input" id="lesson-search" type="search" placeholder="Thử “tế bào”, “ADN” hoặc “lớp 11”…" autocomplete="off"><div id="search-results" class="search-results" aria-live="polite">${lessons.map(resultHTML).join('')}</div>`,'search');document.querySelector('#lesson-search').focus()}
function updateSearch(q){const query=normalize(q.trim()),result=lessons.filter(l=>normalize([l.title,l.kicker,l.description,`lớp ${l.grade}`,l.id==='dna'?'ADN DNA':''].join(' ')).includes(query));document.querySelector('#search-results').innerHTML=result.length?result.map(resultHTML).join(''):'<div class="empty-state">Chưa tìm thấy bài phù hợp. Thử “tế bào”, “nước” hoặc “ADN”.</div>'}
function openPath(){showDialog('Hành trình của riêng bạn','HỘ CHIẾU / 6 ĐIỂM KHÁM PHÁ',`<p class="dialog-lead">Đi từ cấu trúc nhỏ bé đến các quá trình sống. Bạn có thể bắt đầu ở bất cứ đâu.</p><div class="path-list">${lessons.map((l,i)=>`<button class="path-item" data-action="lesson" data-id="${l.id}"><span class="path-number">${state.completed.includes(l.id)?icon('check'):String(i+1).padStart(2,'0')}</span><div><h3>${l.title}</h3><small>Lớp ${l.grade} · ${l.minutes} phút · ${state.completed.includes(l.id)?'Đã hoàn thành':'Chưa khám phá'}</small></div><span>${icon('arrow-up-right')}</span></button>`).join('')}</div><p class="privacy-note">Hoàn thành câu hỏi cuối mỗi bài để ghi dấu khám phá. Không có áp lực về thời gian.</p>`,'path')}
function openPassport(){showDialog('Hộ chiếu khám phá','KHU VƯỜN KIẾN THỨC CỦA BẠN',`<div class="passport-header"><span class="avatar">${icon('sprout')}</span><div><h3>${esc(state.name)}</h3><p>Mỗi câu hỏi là một hạt mầm mới.</p></div></div><div class="stat-grid"><div class="stat-box"><strong>${xpFor(state)}</strong><span>Điểm khám phá XP</span></div><div class="stat-box"><strong>${state.completed.length}/6</strong><span>Bài học đã hoàn thành</span></div><div class="stat-box"><strong>${state.notes.length}</strong><span>Ghi chép của bạn</span></div></div><div class="badge-row">${[['sprout','Mầm tò mò',state.completed.length>0,'Hoàn thành bài học đầu tiên'],['flask','Nhà thực nghiệm',state.trials.length>0,'Ghi một lần thử quang hợp'],['award','Người kết nối',[10,11,12].every(g=>lessons.some(l=>l.grade===g&&state.completed.includes(l.id))),'Hoàn thành ít nhất một bài ở mỗi khối']].map(([ic,n,earned,hint])=>`<div class="journey-badge ${earned?'earned':''}" title="${hint}"><span>${icon(ic)}</span><span>${n}</span><small style="font-size:8px;text-align:center;max-width:150px">${earned?'Đã mở khóa':hint}</small></div>`).join('')}</div><form id="name-form" class="name-form"><label for="explorer-name">Tên khám phá</label><input id="explorer-name" class="name-input" value="${esc(state.name)}" maxlength="40" required><button class="button button-dark" type="submit">Lưu tên</button></form><div class="modal-actions"><button class="button button-dark" data-action="path">Tiếp tục hành trình ${icon('route')}</button><button class="text-button" data-action="notebook">Mở sổ tay ${icon('notebook')}</button></div><p class="privacy-note">Hộ chiếu lưu trên thiết bị này; chưa đồng bộ tài khoản hoặc xếp hạng với người khác.</p>`,'passport')}
function openTeacher(){showDialog('Góc giáo viên','QUAN SÁT QUÁ TRÌNH HỌC',`<p class="dialog-lead">Bảng tổng hợp của người học trên thiết bị này. Dùng để trao đổi sau hoạt động hoặc xuất báo cáo nhỏ cho buổi trình diễn.</p><div class="teacher-note">Bản trải nghiệm chưa có lớp học trực tuyến hay dữ liệu học sinh khác. Các kết quả dưới đây được lấy trực tiếp từ hoạt động trên trình duyệt này.</div><div class="stat-grid"><div class="stat-box"><strong>${state.completed.length}/6</strong><span>Bài học đã hoàn thành</span></div><div class="stat-box"><strong>${state.trials.length}</strong><span>Lần thử thí nghiệm đã lưu</span></div><div class="stat-box"><strong>${state.notes.length}</strong><span>Ghi chép quan sát</span></div></div><div class="report-table-wrap"><table class="trial-table"><thead><tr><th>Khối</th><th>Chủ đề</th><th>Trạng thái</th><th>Gợi ý trao đổi</th></tr></thead><tbody>${lessons.map(l=>`<tr><td>${l.grade}</td><td>${l.title}</td><td>${state.completed.includes(l.id)?'Hoàn thành':'Chưa hoàn thành'}</td><td>${l.id==='photosynthesis'?'Yếu tố giới hạn là gì?':l.id==='mendel'?'Kỳ vọng khác kết quả nhỏ thế nào?':'Hãy giải thích bằng lời của em.'}</td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="button button-dark" data-action="export-report">Xuất báo cáo CSV ${icon('download')}</button><button class="text-button" data-action="path">Xem học liệu ${icon('book-open')}</button></div><p class="privacy-note">Chủ đề THPT được chọn để làm mẫu. Cần giáo viên thẩm định và đối chiếu sách giáo khoa trước khi dùng chính thức.</p>`,'teacher')}
function download(name,body,type){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportNotes(){if(!state.notes.length){toast('Sổ tay chưa có ghi chép để xuất.');return}download('VNScape-so-tay.txt',`SỔ TAY KHÁM PHÁ VNSCAPE\n${state.name}\n\n`+state.notes.map(n=>`${n.title}\n${formatDate(n.date)}\n\n${n.body}`).join('\n\n————————————\n\n'),'text/plain;charset=utf-8');toast('Đã xuất sổ tay dạng văn bản.')}
function exportReport(){const csv=rows=>rows.map(row=>row.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');download('VNScape-tien-do.csv','\uFEFF'+csv([['Lớp','Bài học','Hoàn thành','Điểm lần đầu'],...lessons.map(l=>[l.grade,l.title,state.completed.includes(l.id)?'Có':'Chưa',state.completed.includes(l.id)?30:0])]),'text/csv;charset=utf-8');toast('Đã xuất báo cáo từ hoạt động trên thiết bị này.')}
function openTour(){showDialog('Theo một câu hỏi, đi thật xa.','CHÀO MỪNG ĐẾN VNSCAPE',`<p class="dialog-lead">Đây là một không gian để bạn nhìn, thử và tự rút ra điều mới. Bắt đầu bằng ba bước nhỏ.</p><div class="tour-steps"><div class="tour-step"><span>01</span><h3>Nhìn sâu hơn</h3><p>Chọn lớp 10, 11 hoặc 12. Mở mô hình, xoay và chọn cấu trúc bạn muốn hiểu.</p></div><div class="tour-step"><span>02</span><h3>Thử một giả thuyết</h3><p>Đặt điều kiện cho thí nghiệm quang hợp. Chỉ thay đổi một yếu tố và so sánh kết quả.</p></div><div class="tour-step"><span>03</span><h3>Giữ một phát hiện</h3><p>Trả lời câu hỏi, ghi chép và mở khóa huy hiệu. Hộ chiếu ghi lại hành trình trên thiết bị này.</p></div></div><div class="modal-actions"><button class="button button-dark" data-action="lesson" data-id="cell">Bắt đầu với tế bào ${icon('arrow-right')}</button><button class="text-button" data-action="path">Tự chọn hành trình ${icon('route')}</button></div>`,'tour')}
function openSources(){showDialog('Khoa học cần có nguồn.','THƯ VIỆN / NGUỒN HỌC LIỆU',`<p class="dialog-lead">Nội dung demo được tóm lược và tham khảo từ OpenStax Biology 2e. Đây chưa phải học liệu đã được thẩm định hoặc bộ bài giảng đã đối chiếu đầy đủ Chân trời sáng tạo.</p><ul class="sources-list">${lessons.map(l=>`<li><a href="${l.source}" target="_blank" rel="noopener">${l.title} — OpenStax</a><small>Lớp ${l.grade} · Nguồn tham khảo để kiểm tra và đọc thêm</small></li>`).join('')}</ul><div class="fact-note"><b>Hình ảnh & công nghệ</b><br>Ảnh thiên nhiên: <a href="https://unsplash.com" target="_blank" rel="noopener">Unsplash</a> (các mã ảnh: 1448375240586-882707db888b, 1518531933037-91b2f5f229cc, 1441974231531-c6227db76b6e). Mô hình 3D minh họa được dựng bằng Three.js (MIT); màu và kích thước là quy ước. Phông chữ Be Vietnam Pro và Lora từ Google Fonts, được lưu cùng dự án.</div>`,'sources')}
document.addEventListener('click',e=>{
 const org=e.target.closest('[data-organelle]');if(org){selectOrganelle(org.dataset.organelle);return}
 const answer=e.target.closest('[data-answer]');if(answer){answerQuiz(Number(answer.dataset.answer));return}
 const grade=e.target.closest('[data-grade]');if(grade){state.grade=Number(grade.dataset.grade);persist();renderTopics();document.querySelector(`[data-grade="${state.grade}"]`).focus();return}
 const close=e.target.closest('.close-dialog');if(close){dialog.close();return}
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='model-light'){const lit=!dialog.classList.contains('is-lit');dialog.classList.toggle('is-lit',lit);activeModel?.setLighting(lit);el.setAttribute('aria-pressed',String(lit));return}
 if(a==='model-shell'){if(!activeModel)return;const visible=el.getAttribute('aria-pressed')!=='true';activeModel.setShellVisible(visible);el.setAttribute('aria-pressed',String(visible));el.querySelector('span').textContent=visible?'Thành tế bào':'Hiện thành';return}
 const handlers={lesson:()=>openLesson(el.dataset.id),model:()=>openModel(el.dataset.model),lab:openLab,notebook:()=>openNotebook(),passport:openPassport,path:openPath,tour:openTour,search:openSearch,bookmark:()=>toggleBookmark(el.dataset.id),complete:completeLesson,mission:openMission,'record-trial':recordTrial,'save-lab-note':saveLabNote,'new-note':()=>openNoteForm(el.dataset.title||''),'notes-tab':()=>openNotebook(),'saved-tab':()=>openNotebook('saved'),'edit-note':()=>{const n=state.notes.find(x=>x.id===el.dataset.id);if(n)openNoteForm(n.title,n.body,n.id)},'delete-note':()=>{if(el.dataset.confirm!=='true'){el.dataset.confirm='true';el.textContent='Xác nhận xóa';return}state.notes=state.notes.filter(x=>x.id!==el.dataset.id);persist();openNotebook();toast('Đã xóa ghi chép.')},'export-notes':exportNotes,'export-report':exportReport,teacher:openTeacher,sources:openSources,continue:()=>{const next=lessons.find(x=>x.grade===state.grade&&!state.completed.includes(x.id))||lessons.find(x=>!state.completed.includes(x.id));next?openLesson(next.id):openPassport()},'model-auto':()=>{if(!activeModel)return;const running=activeModel.toggle();el.innerHTML=icon(running?'pause':'play')+` <span>${running?'Tự xoay':'Đã dừng'}</span>`;el.setAttribute('aria-pressed',running)},'model-reset':()=>activeModel?.reset(),'zoom-in':()=>activeModel?.zoomBy(1),'zoom-out':()=>activeModel?.zoomBy(-1),menu:()=>{const nav=document.querySelector('.mobile-nav');nav.hidden=!nav.hidden;el.setAttribute('aria-expanded',!nav.hidden)},about:()=>showDialog('Học từ sự tò mò.','VNSCAPE / BẢN TRẢI NGHIỆM DỰ THI',`<p class="dialog-lead">VNScape là ý tưởng về một bảo tàng sinh học số cho học sinh Việt Nam: kết hợp kiến thức, mô hình và hoạt động tự khám phá.</p><div class="tour-steps"><div class="tour-step"><span>01</span><h3>Nhìn cho hiểu</h3><p>Đưa cấu trúc ra khỏi trang sách bằng mô hình tương tác.</p></div><div class="tour-step"><span>02</span><h3>Thử để biết</h3><p>Biến câu hỏi thành giả thuyết, rồi quan sát kết quả trong mô hình.</p></div><div class="tour-step"><span>03</span><h3>Học có dấu vết</h3><p>Ghi chép điều đã hiểu, điều còn băn khoăn và hành trình đã đi qua.</p></div></div><div class="teacher-note">Bản hiện tại có 6 bài mẫu, 2 mô hình 3D và 1 thí nghiệm. Dữ liệu lưu cục bộ; tài khoản đồng bộ, quản lý lớp, AI và AR chưa được triển khai.</div>`,'about')};handlers[a]?.();
});
document.addEventListener('input',e=>{if(e.target.id==='lesson-search')updateSearch(e.target.value);if(e.target.id==='light-range'||e.target.id==='co2-range')updateLab()});
document.addEventListener('submit',e=>{if(e.target.id==='note-form'){e.preventDefault();const title=e.target.elements.title.value.trim(),body=e.target.elements.body.value.trim();if(!title||!body){toast('Hãy viết tiêu đề và nội dung phát hiện.');return}const id=e.target.dataset.id,n=state.notes.find(x=>x.id===id);if(n){n.title=title;n.body=body;persist()}else addNote(title,body);openNotebook();toast('Đã giữ lại một phát hiện của bạn.')}if(e.target.id==='name-form'){e.preventDefault();const name=document.querySelector('#explorer-name').value.trim();if(!name)return;state.name=name;persist();openPassport();toast('Đã cập nhật tên khám phá.')}});
document.querySelector('.grade-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=[10,11,12].indexOf(state.grade);state.grade=e.key==='Home'?10:e.key==='End'?12:[10,11,12][(index+(e.key==='ArrowRight'?1:2))%3];persist();renderTopics();document.querySelector(`[data-grade="${state.grade}"]`).focus()});
document.querySelectorAll('.mobile-nav a,.mobile-nav button').forEach(el=>el.addEventListener('click',()=>{document.querySelector('.mobile-nav').hidden=true;document.querySelector('.mobile-menu-toggle').setAttribute('aria-expanded','false')}));
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){document.querySelector('.mobile-nav').hidden=true;document.querySelector('.mobile-menu-toggle').setAttribute('aria-expanded','false')}});
document.querySelector('#dna-art').innerHTML=Array.from({length:24},(_,i)=>{const angle=i*.5,width=20+Math.abs(Math.sin(angle))*125,left=50+Math.cos(angle)*3;return `<span class="dna-rung" style="top:${i*8+10}px;width:${width}px;left:${left}%;opacity:${.5+Math.sin(angle)*.3}"></span>`}).join('');
renderTopics();
initExhibition({openModel,selectOrganelle,icon,onRealm:grade=>{state.grade=grade;persist();renderTopics();document.querySelector('#explore').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
